    if (!overrides.jira) return;
    if (!result.jira.statuses) result.jira.statuses = defaults.jira.statuses;
    if (!result.jira.issueTypes) result.jira.issueTypes = defaults.jira.issueTypes;
    if (overrides.jira.questions) {
