        var fn = new Function('module', 'exports', 'require', content);
        fn(moduleObj, moduleObj.exports, function() { return {}; });
        return moduleObj.exports;
    } catch (e) {
        console.warn('configLoader: Failed to evaluate ' + path + ': ' + (e.message || e));
        return null;
    }
