    if (p.indexOf('agents/') === 0) candidates.push(p.substring('agents/'.length));
    if (p.indexOf('./') === 0) candidates.push(p.substring(2));
    for (var i = 0; i < candidates.length; i++) {
        if (tryReadFile(candidates[i]) !== null) return candidates[i];
