  const key = Object.keys(cov).find(k => k.endsWith(suffix));
  if (!key) { console.log(suffix, ': MISSING'); continue; }
  const f = cov[key];
  let s=0, st=0, fnHit=0, fnTot=0;
  for (const id in f.statementMap) { st++; if (f.s[id] > 0) s++; }
  for (const id in f.fnMap) { fnTot++; if (f.f[id] > 0) fnHit++; }
  console.log(suffix, 'stmt:', Math.round(100*s/st)+'% ('+s+'/'+st+')', 'fns:', fnHit+'/'+fnTot);
}
// the new configLoader functions' lines
const key = Object.keys(cov).find(k => k.endsWith('configLoader.js'));
const f = cov[key];
const un = new Set();
for (const id in f.statementMap) if (!f.s[id]) un.add(f.statementMap[id].start.line);
const range = [];
for (let l = 655; l <= 745; l++) if (un.has(l)) range.push(l);
console.log('configLoader 655-745 uncovered:', range.join(',') || 'NONE');
"

